import pytestfrom sqlalchemy import selectfrom test_application import register, token_forfrom vpars_bot.db import ControlCommand, Userfrom vpars_bot.domain import Filters, UserError, parse_price_boundfrom vpars_bot.filter_dialog import build_filters, input_value, new_filter_draft, upgrade_draft@pytest.mark.parametrize("value", ["20 80", "-1", "NaN", "Infinity", "1.001", "1e99"])def test_invalid_single_price_does_not_accept_two_bounds_or_nonfinite_numbers(value):    with pytest.raises(UserError):        parse_price_bound(value)@pytest.mark.parametrize("field", ["brands", "models"])def test_current_filters_enforce_one_brand_and_model(field):    with pytest.raises(UserError, match="лише один"):        Filters(            **{field: ["First", "Second"]},            follow_enabled_sources=True,            sources={"vinted_fr": ["FR"]},        )def test_legacy_draft_is_preserved_and_restarts_at_brand(registry):    old = {        "kind": "filters",        "step": 6,        "values": {            "brands": ["Nike", "Adidas"],            "models": ["Air Max 90", "Air Max 95"],            "sizes": ["EU 42", "EU 43"],            "colors": ["Black"],            "categories": ["Shoes"],            "price": {"currency": "EUR", "minimum": "10", "maximum": "40"},        },    }    draft = upgrade_draft(old, registry)    assert draft["previous_draft"] == old    assert draft["step"] == "brands"    assert draft["values"]["brands"] == ["Nike"]    assert draft["values"]["models"] == ["Air Max 90"]    assert draft["values"]["sizes"] == ["EU 42", "EU 43"]    filters = build_filters(draft, registry)    assert not filters.colors and not filters.categories and not filters.conditions    assert filters.price.maximum == 40async def test_saved_filter_follows_new_markets_and_sends_native_currency_per_source(    services, db, registry):    catalog, control, _ = services    await register(catalog, 101, "alice", 1)    async with db[1].begin() as session:        (await session.get(User, 101)).enabled_sources = ["vinted_fr"]    filters = Filters(        brands=["Nike"],        models=["Air Max 90"],        sizes=["EU 42", "EU 43"],        sources={"vinted_fr": ["FR"]},        follow_enabled_sources=True,        native_prices={"EUR": {"minimum": "20", "maximum": "80"}},    )    item = await catalog.save(101, filters, "new-filter")    await control.start(101, "fr")    fr = await token_for(db[1], source_id="vinted_fr")    assert await control.acknowledge(fr)    await catalog.toggle_marketplace(101, "vinted_de", "enable-de")    await control.start(101, "include-de")    de = await token_for(db[1], source_id="vinted_de")    assert await control.acknowledge(de)    # DE was not in the saved snapshot; current marketplace switches define the scope.    assert "vinted_de" not in (await catalog.get(101, item.id)).filters["sources"]    assert await control.can_deliver(de)    await catalog.toggle_marketplace(101, "vinted_fr", "disable-fr")    assert not await control.can_deliver(fr) and await control.can_deliver(de)    await catalog.toggle_marketplace(101, "vinted_gb", "enable-gb")    await control.start(101, "gb-converted-automatically")    gb = await token_for(db[1], source_id="vinted_gb")    assert await control.acknowledge(gb)    async with db[1]() as session:        commands = list(            (                await session.scalars(                    select(ControlCommand)                    .where(ControlCommand.kind == "start")                    .order_by(ControlCommand.created_at)                )            ).all()        )    latest = {cmd.payload["token"]["source_id"]: cmd.payload["filters"] for cmd in commands}    assert latest["vinted_gb"]["price"] == {        "currency": "GBP",        "minimum": "17.00",        "maximum": "68.00",    }    assert latest["vinted_de"]["price"] == {"currency": "EUR", "minimum": "20", "maximum": "80"}    assert latest["vinted_gb"]["sources"] == {"vinted_gb": ["GB"]}    assert latest["vinted_de"]["sources"] == {"vinted_de": ["DE"]}    assert latest["vinted_gb"]["brands"] == ["Nike"]def test_skipping_both_bounds_is_unlimited_and_zero_is_a_real_bound(registry):    draft = new_filter_draft(registry)    filters = build_filters(draft, registry)    assert registry.for_source(filters, "vinted_gb").price is None    assert registry.for_source(filters, "vinted_fr").price is None    draft["step"] = "price"    draft = input_value(draft, "0 0", 1)    filters = build_filters(draft, registry)    for source in registry.sources:        price = registry.for_source(filters, source).price        assert price.minimum == 0 and price.maximum == 0@pytest.mark.parametrize(    "text,expected",    [        ("л м с", ["L", "M", "S"]),        ("s/M/l, хл; ххл", ["S", "M", "L", "XL", "XXL"]),        ("XS, с, S, м, m", ["XS", "S", "M"]),        ("EU 42, L, 2XL", ["EU 42", "L", "2XL"]),        ("w32, W 32, W34", ["W32", "W34"]),        ("W30 W32 W34", ["W30", "W32", "W34"]),    ],)def test_clothing_sizes_normalize_and_save_without_duplicates(registry, text, expected):    draft = new_filter_draft(registry)    draft["step"] = "sizes"    result = input_value(draft, text, 1)    assert result["values"]["sizes"] == expected    assert build_filters(result, registry).sizes == expected    assert draft["values"] == {}    assert input_value(result, text, 1) == resultdef test_size_batch_rejects_over_limit_without_partially_changing_draft(registry):    draft = new_filter_draft(registry)    draft["step"] = "sizes"    draft["values"]["sizes"] = [f"EU {n}" for n in range(36, 43)]    with pytest.raises(UserError, match="до 8"):        input_value(draft, "M L", 1)    assert len(draft["values"]["sizes"]) == 7